//! Actual immutable original registration and real original value fixpoint/Walker.
use crate::lint::Registry;
#[path="../fixtures/original_policies/untyped_workspace.rs"]mod original;
#[path="../fixtures/native-untyped-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
#[test]fn original_untyped_whole_reports_cover_real_values_dispatch_schemas_maps_and_summaries(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/untyped_workspace.rs"))),"32371963c44a30eee9986997c2dacb6f7a580941");for case in fixture::CASES{let root=scratch::dir(&format!("old-untyped-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["untyped".into()],no_cache:true,raw:true,..Default::default()}).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual original parsing failed for {case}: {:?}",sem.errors);if *case=="noncode"{let mut map_body=false;for ty in sem.objtree.iter_types(){for(_,proc_type)in ty.get().procs.iter(){for body in proc_type.value.iter(){if body.code.is_some()&&sem.file_of(body.location)==Some("maps/untyped.dm"){map_body=true}}}}assert!(map_body,"actual original loader must compile the map body before policy selection is tested");}let outcome=old.run_one(old.reg.lints[0].as_ref());assert!(outcome.internal_error.is_none());if *case=="exempt"{assert!(outcome.run.sites.is_empty());}else{assert!(!outcome.run.sites.is_empty(),"genuine positive {case}");}if *case=="noncode"{assert!(outcome.run.sites.iter().any(|s|s.rel=="code/types.dm"&&s.msg.contains("maps/untyped.dm:2")),"map assignments contribute to actual old code declaration");assert!(!outcome.run.sites.iter().any(|s|s.rel.starts_with("maps/")),"old reports code declarations only");}if *case=="summary"{assert!(outcome.run.sites.iter().any(|s|s.msg.ends_with(" and 2 more")));}assert!(outcome.run.notes.is_empty()&&outcome.allow_used.is_empty());println!("ORIGINAL_UNTYPED_FULL={}",serde_json::json!({"case":case,"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text}));}}
